  const wrapEl = document.createElement('div');
  document.body.appendChild(wrapEl);
  const chess = Chessground(wrapEl, { trustAllEvents: true, ...config });
  const boardEl = wrapEl.querySelector('.cg-board') as HTMLElement;
  boardEl.getBoundingClientRect = () => rect;
